$map=['PDB-3512-S'=>'pakshoma-pdb-3512-s-v367.png','SBS-RSP-800-S-E1'=>'pakshoma-sbs-rsp-800-s-e1-v367.png','UFW-10700-WT'=>'pakshoma-ufw-10700-wt-v367.png'];$base=WP_CONTENT_DIR.'/plugins/baharaan-commerce/includes/bhc-image-references/';foreach($map as $sku=>$file){$id=wc_get_product_id_by_sku($sku);$src=$base.$file;if(!$id||!file_exists($src)){echo $sku."|missing\n";continue;}$im=imagecreatefrompng($src);$w=imagesx($im);$h=imagesy($im);$scale=4096/max($w,$h);$nw=(int)round($w*$scale);$nh=(int)round($h*$scale);$out=imagecreatetruecolor($nw,$nh);imagealphablending($out,false);imagesavealpha($out,true);$c=imagecolorallocatealpha($out,255,255,255,127);imagefilledrectangle($out,0,0,$nw,$nh,$c);imagecopyresampled($out,$im,0,0,0,0,$nw,$nh,$w,$h);$u=wp_upload_bits($file,null,'');if(empty($u['error'])){imagepng($out,$u['file'],6);$old=get_post_thumbnail_id($id);if($old)wp_delete_attachment($old,true);$aid=wp_insert_attachment(['post_mime_type'=>'image/png','post_title'=>get_the_title($id).' تصویر اختصاصی','post_status'=>'inherit'],$u['file'],$id);require_once ABSPATH.'wp-admin/includes/image.php';wp_update_attachment_metadata($aid,wp_generate_attachment_metadata($aid,$u['file']));set_post_thumbnail($id,$aid);update_post_meta($id,'_bhc_image_generation_status','generated_4k_transparent_verified');echo $id.'|'.$nw.'x'.$nh."\n";}imagedestroy($im);imagedestroy($out);}
